48	const PROCESSING_FEE = 5;
49	const FIRST_INSURANCE_SURCHARGE = 0.1;
50	
51	const BASE_PREMIUMS: Record<string, number> = {
52	  sword: 100,
53	  amulet: 60,
54	  staff: 80,
55	  potion: 40,
56	  rune: 25,
57	};
58	
59	const quotePremium = (items: Item[]): number => {
60	  const policyBasePremium = items.reduce(
61	    (sum, item) => sum + BASE_PREMIUMS[item.type],
62	    0,
63	  );
64	  return Math.ceil(
65	    policyBasePremium +
66	      policyBasePremium * FIRST_INSURANCE_SURCHARGE +
67	      PROCESSING_FEE,
68	  );
69	};
70	
71	const runStep = (step: Step): StepResult => {
72	  if (step.op === "quote") {
73	    return { premium: quotePremium(step.items) };
74	  }
75	  throw new Error(`Unsupported step: ${step.op}`);
76	};
77	
78	export const runScenario = (scenario: Scenario): ScenarioResult => ({
79	  results: scenario.steps.map(runStep),
80	});
