/** Premiums are rounded up — in MHPCO's favour. */
const roundPremium = (amount: number): number => Math.ceil(amount);

const quotePremium = (items: Item[]): number => {
  const policyBasePremium = items.reduce(
    (sum, item) => sum + BASE_PREMIUMS[item.type],
    0,
  );
  const withFirstInsuranceSurcharge =
    policyBasePremium * (1 + FIRST_INSURANCE_SURCHARGE);
  return roundPremium(withFirstInsuranceSurcharge + PROCESSING_FEE);
};

